import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
export function build(directory=fileURLToPath(new URL('.',import.meta.url)),check=false){
  const expected='// Generated by build.mjs from states.json.\nwindow.jigStateTable = '+JSON.stringify(JSON.parse(readFileSync(resolve(directory,'data/states.json'),'utf8')))+';\n';
  const target=resolve(directory,'data/states.js');
  if(check){if(readFileSync(target,'utf8')!==expected)throw new Error('State fixture drift; run its build.mjs');}else writeFileSync(target,expected);
}
if(process.argv[1]&&pathToFileURL(resolve(process.argv[1])).href===import.meta.url)build(undefined,process.argv.includes('--check'));
